  &lt;!-- Batik Pattern (simplified abstract) --&gt;
  &lt;defs&gt;
    &lt;pattern id=&quot;batikPattern&quot; patternUnits=&quot;userSpaceOnUse&quot; width=&quot;20&quot; height=&quot;20&quot;&gt;
      &lt;circle cx=&quot;5&quot; cy=&quot;5&quot; r=&quot;2&quot; fill=&quot;#FF6B3A&quot;/&gt;
