      &lt;line x1=&quot;10&quot; y1=&quot;0&quot; x2=&quot;10&quot; y2=&quot;20&quot; stroke=&quot;#FF6B3A&quot; stroke-width=&quot;1&quot;/&gt;
    &lt;/pattern&gt;
  &lt;/defs&gt;

  &lt;!-- Main Symbol A --&gt;
